import json
import subprocess
import sys
from pathlib import Path

from app.services import users

_SLUG_SCRIPT = Path(__file__).resolve().parents[2] / "scripts" / "slug.py"


def _is_valid_title(title: object) -> bool:
    """A title is valid when it is a 1-80 character string with an ASCII letter or digit."""
    if not isinstance(title, str):
        return False
    if not 1 <= len(title) <= 80:
        return False
    return any(char.isascii() and char.isalnum() for char in title)


def _run_slug_script(title: str) -> str:
    """Run scripts/slug.py for a title and return the slug it prints."""
    script = str(_SLUG_SCRIPT)
    # Titles starting with "-" would be parsed as an option, so pass them inline.
    if title.startswith("-"):
        command = [sys.executable, script, f"--title={title}"]
    else:
        command = [sys.executable, script, "--title", title]
    result = subprocess.run(command, capture_output=True, text=True, check=True)
    return json.loads(result.stdout)["slug"]


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_make_slug(params: dict) -> tuple[int, dict]:
    title = params.get("title")
    if not _is_valid_title(title):
        return 400, {"error": "invalid title"}
    return 200, {"slug": _run_slug_script(title)}
"}

